-- Rangefinder NPC lock configuration
-- Set to false if you do not want NPC locking at all.
RangefinderNPCLockEnabled = true

-- Hold this key to lock onto an NPC.
RangefinderNPCLockKey = KEY_E

-- Time in seconds the target must stay in focus before lock is acquired.
RangefinderNPCLockHoldTime = 0.7

-- Maximum lock distance in meters (0 = unlimited).
RangefinderNPCLockMaxDistanceMeters = 500

-- Aim precision required for locking (0.0 - 1.0, higher = stricter).
RangefinderNPCLockAimDotThreshold = 0.992

-- Grace period before a lock breaks when LOS/aim is lost.
RangefinderNPCLockBreakGraceTime = 0.35

-- If true, camera aim stays centered on the locked NPC while lock is active.
RangefinderNPCLockAimAssist = true

-- Key bindings (can be changed to your preference)
-- Das sind die Standardwerte. Spieler koennen sie ingame mit /binds selbst aendern.
-- Fernglas (Binoculars)
KEY_TOGGLE          = KEY_J
KEY_ZOOM            = KEY_B
KEY_NIGHT           = KEY_N
KEY_UNZOOM          = KEY_G
KEY_THERMAL         = KEY_O
KEY_THERMAL_MODIFIER = nil
KEY_RANGEFINDER     = KEY_J

